  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Flyt hele den gemte samtale, tjeklisten, vedhæftningerne og filerne. Udbydersessioner og legitimationsoplysninger bliver her. Tråden på destinationen bruger computerens standardharness og får ikke mere adgang end denne tråd. Intet køres, før du sender den næste besked dér. Du kan ændre dens model, når den er åbnet. Denne tråd bliver her skrivebeskyttet, så den kan gendannes.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Kopiér filer og lokal Git-historik. Kildeprojektet og chats bliver her. Der oprettes en ny mappe på destinationen. Worktrees bruger den konfigurerede worktree-mappe.',
