  'Enable agent computer use on this computer': 'Aktivér agentens computerbrug på denne computer',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Giver agenter med skriveadgang adgang til denne computers skrivebord. Agenter med skrivebeskyttet adgang er undtaget. Brugeren og agenterne deler skrivebordet og appens tilstand.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Lad Cua Driver-feltet være tomt for at finde programmet på denne computers PATH eller i standardinstallationsmappen. Ændringer gælder for nye agentture.',
  '1. Install on this computer': '1. Installer på denne computer',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Kør det officielle installationsprogram på runtimeværten, og opdatér derefter status. Det downloader og installerer CuaDriver; en Cua-konto er ikke nødvendig.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimalistiske Linux-systemer kræver libxi6 og at-spi2-core. GNOME kræver Cuas medfølgende WinRects-hjælpeprogram; se installationsvejledningen.',
  'Install and set up Cua Driver': 'Installer og konfigurér Cua Driver',
  'Detect / check Cua Driver': 'Find / kontrollér Cua Driver',
  '2. Permissions & desktop access': '2. Tilladelser og skrivebordsadgang',
  '3. Agent MCP, skills & hooks': '3. Agent-MCP, skills og hooks',
  '4. Computer History (optional preview)': '4. Computer History (valgfri forhåndsvisning)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Giv CuaDriver adgang til Tilgængelighed og Skærmoptagelse i macOS, og accepter genstarten. Test af skrivebordsadgang viser apps uden at ændre dem. Daemon-kontroller påvirker aktive computerbrugssessioner.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Gem computerbrugskontakten for automatisk dovo_cua MCP på nye ture med skriveadgang. Manuel MCP-registrering er ikke nødvendig. Installer den valgfrie officielle skill-pakke; installationen tilknytter fundne agenter på denne computer.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Tilvælgelse, krypteret historik, kun metadata. Aktivering kan genstarte daemonen. Deaktivering beholder registrerede data; pause stopper optagelsen midlertidigt. Ikke-understøttede builds viser en fejl. Dataene forbliver på runtimeværten; Hent seneste historik viser op til 20 hændelser her.',
  'Delete recorded Computer History?': 'Slet registreret Computer History?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Slet al registreret historik og dens krypteringsnøgle på denne computer. Dette kan ikke fortrydes.',
