  'Enter the new address and a fresh pairing code from the same computer. Your saved connection stays unchanged until pairing succeeds.':
    'Indtast den nye adresse og en ny parringskode fra den samme computer. Din gemte forbindelse forbliver uændret, indtil parringen lykkes.',
  'On your computer, open Dovo and choose {value0} in Settings → Devices & runtime.':
    'Åbn Dovo på computeren, og vælg {value0} under Indstillinger → Enheder og runtime.',
