  'Dovo Connect: {value0}': 'Dovo Connect: {value0}',
  'Pair again': 'Par igen',
  'Connection stages': 'Forbindelsesfaser',
  'Start your computer': 'Start computeren',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Åbn Dovo på computeren, og sørg for, at den ikke går i dvale. Gå til Indstillinger → Enheder og runtime, log ind, og aktivér Dovo Connect. Log ind på den samme konto på telefonen, og vælg Opret forbindelse. Der kræves ingen parringskode, VPN eller lokal IP-adresse for internetadgang.',
  'Direct internet connection': 'Direkte internetforbindelse',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN forbinder telefonen direkte med computeren. Dit indhold er end-to-end-krypteret. Når Dovo Connect aktiveres, tillades en krypteret relay-forbindelse, hvis et netværk blokerer direkte forbindelser. Relæet videresender krypteret trafik og kan ikke læse dit indhold.',
  'LAN / VPN connections': 'LAN-/VPN-forbindelser',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Par LAN/VPN separat for at foretrække den forbindelse, når den er tilgængelig. Kopiér hele Wi-Fi-, Tailscale-, NetBird- eller HTTPS-adressen, der vises på computeren, inklusive porten. localhost og 0.0.0.0 er ikke adresser, som telefonen kan oprette forbindelse til.',
  'Check your network': 'Tjek dit netværk',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Brug det samme Wi-Fi-netværk, eller forbind begge enheder til din VPN. Ved Wi-Fi-forbindelser skal du give Dovo adgang til dit lokale netværk i iPhone-indstillinger.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Parringskoder udløber efter to minutter. CLI-koder godkendes automatisk; en kode fra skrivebordsappen skal muligvis godkendes dér.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Din parring er gemt. Prøv at oprette forbindelse igen, før du genererer en ny kode. Hvis adressen er ændret, skal du vælge Opdater forbindelsesadresse i indstillingerne for denne computer.',
