  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Kører agenten for hver ny samtale, dens kommandoer og dens terminaler i en lokal Docker- eller Podman-container. Kun arbejdskopien og den valgte agents login monteres. Igangværende samtaler beholder deres indstilling.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Uden netværksadgang kan agenten ikke nå sin models API, medmindre den API kører i sandkassen. Pakkeinstallationer og webanmodninger mislykkes også.',
