  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agenten, dens kommandoer og dens terminaler kører i en container. Kun denne arbejdskopi og agentens login monteres.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Holder nyt arbejde, der kører uden din besked, tilbage, når den anslåede omkostning når grænsen. Det gælder opfølgninger fra Bots, rutinetrin i en Bot, planlagte beskeder og underagenter. Hver tråd eller Bot tæller sammen med sine underagenter. En rutine uden Bot starter en ny optælling ved hver kørsel. Angiv dens egne grænser under Overvågning og grænser. Din næste besked eller Fortsæt nulstiller optællingen. Ture uden pris holder også arbejde tilbage. En igangværende tur gøres altid færdig.',
  'During your request: "{value0}"': 'Under din anmodning: "{value0}"',
